<script setup>
import { useDialogEscape } from '../../lib/dialog.js';
import { ref } from 'vue';
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import Errors from '../../Components/Errors.vue';
const props=defineProps({words:{type:Object,default:()=>({data:[],links:[]})},filters:{type:Object,default:()=>({})}});
const search=ref(props.filters.search??'');
const editing=ref(null); const open=ref(false);
const form=useForm({term:'',definition:'',note:''});
function edit(word=null){editing.value=word?.id??null;form.clearErrors();form.term=word?.term??'';form.definition=word?.definition??'';form.note=word?.note??'';open.value=true;}
function save(){const options={onSuccess:()=>{open.value=false;form.reset();}};editing.value?form.put(`/words/${editing.value}`,options):form.post('/words',options);}
function remove(word){if(confirm(`Delete “${word.term}” from your pool and collections?`))router.delete(`/words/${word.id}`);}
useDialogEscape(()=>{open.value=false;});
</script>
<template><Head title="Word pool"/><AppLayout title="Your word pool." subtitle="Every word is a small discovery."><template #actions><div class="actions"><Link href="/imports" class="button secondary">Import CSV</Link><button class="button" @click="edit()">+ Add a word</button></div></template><form class="search-row" @submit.prevent="router.get('/words',{search:search},{preserveState:true,replace:true})"><input v-model="search" type="search" placeholder="Search words and definitions…" aria-label="Search words"/><button class="button secondary">Search</button><span class="muted">{{words.total ?? words.data.length}} words</span></form><div class="word-list"><article class="word-row editable" v-for="word in words.data" :key="word.id"><div><strong>{{word.term}}</strong><p>{{word.definition}}</p><div v-if="word.note" class="personal-note"><span>YOUR NOTE</span>{{word.note}}</div></div><div class="actions"><button class="text-button" @click="edit(word)">Edit</button><button class="text-button danger" @click="remove(word)">Delete</button></div></article><div v-if="!words.data.length" class="empty"><span>≋</span><h3>{{search?'No matching words.':'A blank page, full of possibility.'}}</h3><p>{{search?'Try another search.':'Add a word or bring your vocabulary in with a CSV.'}}</p><button v-if="!search" class="button" @click="edit()">Add your first word</button></div></div><nav class="pagination" aria-label="Pagination"><template v-for="(link,index) in words.links" :key="index"><Link v-if="link.url" :href="link.url" :class="{active:link.active}" v-html="link.label"/><span v-else v-html="link.label"/></template></nav><div v-if="open" class="modal-backdrop" @click.self="open=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="word-title"><div class="section-heading"><h2 id="word-title">{{editing?'Edit word':'A new discovery'}}</h2><button class="icon-button" aria-label="Close" @click="open=false">×</button></div><form @submit.prevent="save"><Errors :errors="form.errors"/><label>Word or phrase<input v-model="form.term" required maxlength="500" autofocus/></label><label>Original definition<textarea v-model="form.definition" maxlength="5000" required rows="3"/></label><label>Your private note<textarea v-model="form.note" maxlength="5000" rows="2" placeholder="A translation, a memory, a little context…"/></label><p class="muted small">Personal notes never appear on shared collection links.</p><div class="form-actions"><button type="button" class="button secondary" @click="open=false">Cancel</button><button class="button" :disabled="form.processing">Save word</button></div></form></section></div></AppLayout></template>
